<script setup lang="ts">
import {computed,ref} from 'vue'
const props=defineProps<{value:any}>(),search=ref('')
const rows=computed(()=>props.value.ips.filter((row:any)=>!search.value||[row.ip,row.country,row.province,row.city,...row.userNames].join(' ').toLowerCase().includes(search.value.toLowerCase())))
const distributions=[['网络类型','networks'],['国家或网络范围','countries'],['省份或地区','provinces'],['城市','cities']]
function date(value:string){return value?new Date(value).toLocaleString():'未记录'}
</script>
<template>
 <div v-if="props.value" class="visitor-traffic">
  <div class="traffic-cards"><article v-for="[label,key] in [['页面访问次数','pageViews'],['独立 IP 数','uniqueIps'],['登录访问用户','loggedInUsers'],['未登录访问次数','anonymousViews'],['历史 IP 未记录','missingIpViews']]" :key="key"><b>{{props.value.summary[key]}}</b><span>{{label}}</span></article></div>
  <p class="traffic-note">日期与用户筛选应用于访问统计。地域分布按页面访问次数计算；独立 IP 数可能对应校园网、VPN 或共享出口。</p>
  <p class="traffic-note">离线地域库：IPv4 {{props.value.databaseReady.ipv4?'已启用':'未启用'}} · IPv6 {{props.value.databaseReady.ipv6?'已启用':'未启用'}}</p>
  <div class="traffic-charts"><section v-for="[title,key] in distributions" :key="key" class="traffic-panel"><h3>{{title}}</h3><p v-if="!props.value[key].length">暂无访问记录</p><div v-for="row in props.value[key]" :key="row.label" class="traffic-bar"><span :title="row.label">{{row.label}}</span><div><i :style="{width:row.percent+'%'}"></i></div><b>{{row.count}}</b><small>{{row.percent}}%</small></div></section></div>
  <section class="traffic-panel"><h3>访问 IP 明细</h3><el-input v-model="search" clearable placeholder="搜索 IP、地域或用户名"/><el-table :data="rows" stripe max-height="520"><el-table-column prop="ip" label="IP 地址" min-width="160"/><el-table-column prop="networkLabel" label="网络类型" min-width="120"/><el-table-column label="大致地域" min-width="180"><template #default="s">{{[s.row.country,s.row.province,s.row.city].filter(Boolean).join(' · ')||'无法从该地址判断实际地域'}}<p>{{s.row.isp}}</p></template></el-table-column><el-table-column prop="views" label="访问次数" width="95"/><el-table-column label="关联登录用户" min-width="160"><template #default="s">{{s.row.userNames.join('、')||'未登录'}}</template></el-table-column><el-table-column label="首次访问" min-width="160"><template #default="s">{{date(s.row.firstSeen)}}</template></el-table-column><el-table-column label="最近访问" min-width="160"><template #default="s">{{date(s.row.lastSeen)}}</template></el-table-column></el-table></section>
  <section class="traffic-panel"><h3>每日访问</h3><el-table :data="props.value.daily" stripe max-height="380"><el-table-column prop="date" label="日期"/><el-table-column prop="pageViews" label="页面访问"/><el-table-column prop="uniqueIps" label="独立 IP"/><el-table-column prop="loggedInUsers" label="登录用户"/></el-table></section>
  <section class="traffic-panel"><h3>统计说明</h3><ul><li v-for="note in props.value.notes" :key="note">{{note}}</li></ul></section>
 </div>
</template>
<style scoped>.traffic-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px}.traffic-cards article,.traffic-panel{background:white;border:1px solid #dce8e0;border-radius:12px;padding:18px}.traffic-cards b{display:block;font-size:26px;color:#23664c}.traffic-cards span{font-size:12px;color:#728579}.traffic-panel{margin:16px 0}.traffic-panel h3{margin:0 0 14px}.traffic-charts{display:grid;grid-template-columns:1fr 1fr;gap:16px}.traffic-bar{display:grid;grid-template-columns:120px 1fr 35px 50px;gap:8px;font-size:13px;align-items:center;margin:12px 0}.traffic-bar>span{overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.traffic-bar>div{height:10px;background:#edf3ef;border-radius:8px;overflow:hidden}.traffic-bar i{display:block;height:100%;background:#3a8d69}.traffic-note,.traffic-panel ul{font-size:13px;color:#6b8076;line-height:1.8}.traffic-panel :deep(.el-table){font-size:13px}.traffic-panel :deep(.el-input){margin-bottom:12px}@media(max-width:800px){.traffic-charts{grid-template-columns:1fr}.traffic-panel{padding:12px}.traffic-bar{grid-template-columns:100px 1fr 25px 45px;gap:5px}}</style>
